import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"键与完整性","description":"","frontmatter":{"title":"键与完整性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/keys-integrity.md","filePath":"cs/keys-integrity.md","lastUpdated":1789023840000}'),c={name:"cs/keys-integrity.md"};function h(A,a,B,_,m,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="键与完整性" tabindex="-1">键与完整性 <a class="header-anchor" href="#键与完整性" aria-label="Permalink to &quot;键与完整性&quot;">​</a></h1><div class="epigraph"><p>键把元组从集合里可识别出来；外键把引用从指针改成值上的约束。</p><footer>—— 据 Codd 1970；Date, An Introduction to Database Systems 整理</footer></div><p><a href="/cs/er-to-rel">上一课</a>把事实命名成关系：属性上的元组集合，连接靠值相等。本课不重讲域与模式。缺口是：集合里的元组如何被唯一指称，以及一个关系里的值如何合法地指向另一个关系里的元组。没有这两条，更新会留下重复身份和悬挂引用，后课代数只是在脏数据上做闭包。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>关系是集合，本来没有重复元组。实践里同一实体可以出现两次，只因少了一个能区分身份的属性子集。超键是能函数决定全部属性的属性集；候选键是极小超键；主键是被指定的那个候选键。缺口不是「主键按钮」，而是：<strong>身份必须是值上的约束</strong>，不能靠文件偏移。</p><p>外键是另一关系候选键的引用。参照完整性要求：外键为空（若允许）或等于被参照关系中已存在的键值。删除或更新被参照元组时，拒绝、级联或置空是策略，不是完整性的定义。实体完整性：主键属性不空——否则「这一行是谁」没有答案。</p><p><span class="marginnote">函数依赖 \\(X\\to Y\\)：任何两元组若在 \\(X\\) 上相等，则在 \\(Y\\) 上相等。键是能决定全部属性的 \\(X\\)。范式课才系统用依赖，本课只用它定义键。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在模式上声明候选键与外键，作为所有实例必须满足的断言。检查发生在插入、删除、更新的边界，而不是查询时事后过滤。声明是逻辑的：物理上可以用<a href="/cs/btree-external">B 树</a>做唯一索引，那是后课存储的实现，不是完整性的含义。</p><p>用户定义的检查（域约束、CHECK）同属完整性，本课不枚举。Codd 把完整性与数据独立性绑在一起：约束写在模式上，应用不必在每条更新路径手写同一段检查。</p>',10)),(e(),l(p,null,{default:r(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22%E5%85%B3%E7%B3%BB%E6%A8%A1%E5%BC%8F%22%5D%20--%3E%20SK%5B%22%E8%B6%85%E9%94%AE%20%2F%20%E5%80%99%E9%80%89%E9%94%AE%20%2F%20%E4%B8%BB%E9%94%AE%22%5D%0A%20%20REL%20--%3E%20FK%5B%22%E5%A4%96%E9%94%AE%3A%20%E5%80%BC%E5%BC%95%E7%94%A8%22%5D%0A%20%20SK%20--%3E%20EI%5B%22%E5%AE%9E%E4%BD%93%E5%AE%8C%E6%95%B4%E6%80%A7%22%5D%0A%20%20FK%20--%3E%20RI%5B%22%E5%8F%82%E7%85%A7%E5%AE%8C%E6%95%B4%E6%80%A7%22%5D%0A%20%20EI%20--%3E%20ALG%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%85%B3%E7%B3%BB%E4%BB%A3%E6%95%B0%22%5D%0A%20%20RI%20--%3E%20ALG%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了键，元组有了稳定身份：复制、更新、删除可以指向「这个键值」，而不指向「现在的第 7 个槽」。有了外键，连接条件常常就是外键等于主键；悬挂引用被拒绝，连接不会默默丢语义。后课规范化会问键是否「太小或太大」；本课只要求键存在且被声明。</p><p>多属性键合法。替代键（UNIQUE）与主键同一机制，只是被参照时通常选一个。本课不引入代理键与自然键的宗教争论：两者都是候选键，差别在稳定性与含义，不是完整性公理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲触发器实现，不把完整性当成「业务规则引擎」。也不预支事务：约束在单条语句边界检查还是在提交时检查，是<a href="/cs/acid">ACID</a>与隔离的缺口。NULL 与外键的组合（「不知道引用谁」）留给 SQL；这里只钉值引用必须可判定。</p><p>后课默认：谈到关系，已有候选键；谈到跨表引用，已有外键。代数把键当普通属性用，不把约束再推导一遍。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上一课有关系，本课补身份与引用：候选键、主键、外键。</li><li>实体完整性与参照完整性是模式上的断言，不是文件指针。</li><li>函数依赖只用来定义键；范式是后课。</li><li>出处：Codd, 1970；Date；Ramakrishnan and Gehrke, <em>Database Management Systems</em>。</li></ul>',8))])}const b=s(c,[["render",h]]);export{C as __pageData,b as default};
